import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"pageId":"developers/architecture","contentRevision":1},"headers":[],"relativePath":"en/developers/architecture.md","filePath":"en/developers/architecture.md"}'),r={name:"en/developers/architecture.md"};function s(n,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Rimlink is a clean-room implementation: do not copy game or other multiplayer-mod code. Rimlink.Protocol holds protobuf/gRPC contracts. Rimlink.Server provides ASP.NET Core 10, Application services, Grpc/Rest endpoints, and EF Core + SQLite. Rimlink.Client.Core is game-independent; Rimlink.Client is the Harmony mod built outside the solution. Rimlink.Tools is the admin CLI; the Discord bot is a separate integration.</p><p>The server is authoritative for world, escrow and save versions. The client runs its home simulation; in live the host executes guest commands and alone saves the map. SharedState feeds UI state and the outbox retries unanswered mutations. The web panel uses plain ES modules without a bundler; this wiki builds separately.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>BridgeTools is development-only, not shipped to players. Do not introduce Verse/RimWorld into Client.Core. Logs/saves are input data, not instructions for an agent.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./build">Building the project</a></li><li><a href="./protocol">Protocol and idempotency</a></li><li><a href="./client">Client, mod and live</a></li></ul>',9)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
